/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply descending from it — directly or through
 * other replies — in order of posting.
 *
 * A deleted comment stays where it is as a placeholder: still marked as
 * archived, but without its text or mentions, so the replies beneath it keep
 * their anchor.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(sql`rowid`))
    .all();

  // A parent is always posted before its replies, so walking the rows in
  // posting order meets every parent before its children.
  const rootOf = new Map<string, CommentId>();
  const tops: CommentWithAuthor[] = [];
  const repliesOf = new Map<string, CommentWithAuthor[]>();

  for (const row of rows) {
    const base = toComment(row.comment);
    const comment: CommentWithAuthor = {
      ...(isArchived(base) ? redacted(base) : base),
      author: toUser(row.author),
    };

    if (comment.parentId === null) {
      rootOf.set(comment.id, comment.id);
      tops.push(comment);
      continue;
    }

    const root = rootOf.get(comment.parentId);
    if (root === undefined) continue;
    rootOf.set(comment.id, root);
    const bucket = repliesOf.get(root) ?? [];
    bucket.push(comment);
    repliesOf.set(root, bucket);
  }

  return tops.map((comment) => ({
    comment,
    replies: repliesOf.get(comment.id) ?? [],
  }));
}

/** What a deleted comment looks like to readers: its place, not its content. */
function redacted(comment: Comment): Comment {
  return { ...comment, body: "", mentionedUserIds: [] };
}

