subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const comment = await commentRepo.findCommentById(
    payload.orgId,
    payload.commentId,
  );
  const repliedTo =
    comment?.parentId === null || comment?.parentId === undefined
      ? null
      : await commentRepo.findCommentById(payload.orgId, comment.parentId);

  // A mention outranks the comment alert, so anyone mentioned is left out of
  // the comment recipients and each person hears about this comment once.
  const mentioned = new Set<UserId>(payload.mentionedUserIds);
  const watchers = issue
    ? [
        issue.authorId,
        issue.assigneeId,
        repliedTo?.authorId ?? null,
      ]
    : [];
  const commentRecipients = watchers.filter(
    (userId): userId is UserId => userId !== null && !mentioned.has(userId),
  );

  await notify(payload.orgId, "comment_created", commentRecipients, {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  await notify(payload.orgId, "comment_mention", payload.mentionedUserIds, {
    title: "You were mentioned",
    body: `You were mentioned on issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });
});

