              .map((reply) => (
                <CommentItem
                  key={reply.id}
                  comment={reply}
                  actor={actor}
                  depth={1}
                  onDelete={onDelete}
                  {...(onEdit !== undefined ? { onEdit } : {})}
                />
              ))}
          </ol>
        </li>
      ))}
    </ol>
  );
}

/**
 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, asc, count, desc, eq, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, isArchived, shouldFilterArchived } from "@/lib/soft-delete";
import { comments, getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toComment, toUser } from "./_mappers";
import type {
  CreateCommentInput,
  ListCommentsInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type {
  Comment,
  CommentThreadNode,
  CommentWithAuthor,
} from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";

export async function findCommentById(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment | null> {
  const row = getDb()
    .select()
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .get();
  return row ? toComment(row) : null;
}

export async function listComments(
  input: ListCommentsInput,
): Promise<Page<CommentWithAuthor>> {
  const db = getDb();
  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };

  const filters = compact(
    orgPredicate(comments.orgId, input.orgId),
    eq(comments.issueId, input.issueId),
    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
  );

  const total = db
    .select({ value: count() })
    .from(comments)
    .where(and(...filters))
    .get();

  const rows = db
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(comments.createdAt), desc(comments.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
  );
}

/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply descending from it — directly or through
 * other replies — in order of posting.
 *
 * A deleted comment stays where it is as a placeholder: still marked as
 * archived, but without its text or mentions, so the replies beneath it keep
 * their anchor.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(sql`rowid`))
    .all();

  // A parent is always posted before its replies, so walking the rows in
  // posting order meets every parent before its children.
  const rootOf = new Map<string, CommentId>();
  const tops: CommentWithAuthor[] = [];
  const repliesOf = new Map<string, CommentWithAuthor[]>();

  for (const row of rows) {
    const base = toComment(row.comment);
    const comment: CommentWithAuthor = {
      ...(isArchived(base) ? redacted(base) : base),
      author: toUser(row.author),
    };

    if (comment.parentId === null) {
      rootOf.set(comment.id, comment.id);
      tops.push(comment);
      continue;
    }

    const root = rootOf.get(comment.parentId);
    if (root === undefined) continue;
    rootOf.set(comment.id, root);
    const bucket = repliesOf.get(root) ?? [];
    bucket.push(comment);
    repliesOf.set(root, bucket);
  }

  return tops.map((comment) => ({
    comment,
    replies: repliesOf.get(comment.id) ?? [],
  }));
}

/** What a deleted comment looks like to readers: its place, not its content. */
function redacted(comment: Comment): Comment {
  return { ...comment, body: "", mentionedUserIds: [] };
}

export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        isNull(comments.archivedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

/**
 * An edit stamps `edited_at`, which the UI shows next to the timestamp. The
 * mention list is rewritten alongside the body so the row always agrees with
 * the text it was written from.
 */
export async function updateComment(
  input: UpdateCommentInput,
  mentionedUserIds: readonly UserId[],
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({
      body: input.body,
      mentionedUserIds: JSON.stringify(mentionedUserIds),
      editedAt: stamp,
      updatedAt: stamp,
    })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

export async function archiveComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const row = getDb()
    .update(comments)
    .set(archivePatch())
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${commentId} not found`);
  return toComment(row);
}
